import { useEffect, useRef, useState } from "react";
import {
  fontDisplay, color, motion, type,
} from "../../theme";

/** Sticky compact title that appears once the page hero scrolls away. No mark: the page is the identity. */
export default function CollapsingHeader({ title, subtitle }) {
  const sentinelRef = useRef(null);
  const [compact, setCompact] = useState(false);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    let root = sentinel.parentElement;
    while (root && root !== document.body) {
      const { overflowY } = window.getComputedStyle(root);
      if (overflowY === "auto" || overflowY === "scroll") break;
      root = root.parentElement;
    }
    if (!root || root === document.body) root = null;

    const io = new IntersectionObserver(
      ([entry]) => setCompact(!entry.isIntersecting),
      { root, threshold: 0, rootMargin: "-56px 0px 0px 0px" }
    );
    io.observe(sentinel);
    return () => io.disconnect();
  }, []);

  return (
    <>
      <div ref={sentinelRef} aria-hidden="true" style={{ height: 1 }} />
      <div
        aria-hidden={!compact}
        style={{
          position: "sticky",
          top: 0,
          zIndex: 40,
          height: 48,
          marginTop: -1,
          marginBottom: -48,
          opacity: compact ? 1 : 0,
          overflow: "hidden",
          pointerEvents: compact ? "auto" : "none",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          background: "rgba(10,13,17,0.94)",
          borderBottom: compact ? "1px solid rgba(255,255,255,0.08)" : "none",
          transition: `opacity ${motion.base} ${motion.ease}`,
        }}
      >
        <div style={{
          fontSize: 16, fontWeight: 650, letterSpacing: -0.3,
          color: color.ink, fontFamily: fontDisplay,
        }}>
          {title}
        </div>
      </div>
      <div style={{
        padding: subtitle ? "28px 16px 12px" : "32px 22px 18px",
        opacity: compact ? 0 : 1,
        transform: compact ? "translateY(-6px)" : "none",
        transition: `opacity ${motion.base} ${motion.ease}, transform ${motion.base} ${motion.ease}`,
        pointerEvents: compact ? "none" : "auto",
      }}>
        <h1 style={{
          margin: 0,
          ...type.largeTitle,
          color: color.ink,
        }}>
          {title}
        </h1>
        {subtitle ? (
          <p style={{
            margin: "10px 0 0",
            fontSize: 15,
            color: color.body,
            lineHeight: 1.45,
          }}>
            {subtitle}
          </p>
        ) : null}
      </div>
    </>
  );
}
